import{_ as a,o as t,c as o,aQ as r}from"./chunks/framework.cDvftfeu.js";const m=JSON.parse('{"title":"MCP 服务","description":"Ham MCP 服务介绍 — 通过 MCP 协议将 Ham 的能力接入你的 AI 助手。","frontmatter":{"description":"Ham MCP 服务介绍 — 通过 MCP 协议将 Ham 的能力接入你的 AI 助手。","next":{"text":"配置指南","link":"/guide/mcp/config"}},"headers":[],"relativePath":"guide/mcp/index.md","filePath":"guide/mcp/index.md","lastUpdated":1779798458000}'),l={name:"guide/mcp/index.md"};function i(n,e,c,s,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="mcp-服务" tabindex="-1">MCP 服务 <a class="header-anchor" href="#mcp-服务" aria-label="Permalink to &quot;MCP 服务&quot;">​</a></h1><p>Ham 提供 MCP（Model Context Protocol）服务，允许你将 Ham 的校园数据与能力接入支持 MCP 的 AI 助手（如 Claude Desktop、Cursor 等）。</p><h2 id="什么是-mcp" tabindex="-1">什么是 MCP？ <a class="header-anchor" href="#什么是-mcp" aria-label="Permalink to &quot;什么是 MCP？&quot;">​</a></h2><p>MCP（<a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a>）是一个开放协议，让 AI 应用能够安全地连接外部数据源和工具。通过 Ham 的 MCP 服务，你的 AI 助手可以：</p><ul><li>查询课程信息与成绩</li><li>查看个人信息</li></ul><h2 id="服务地址" tabindex="-1">服务地址 <a class="header-anchor" href="#服务地址" aria-label="Permalink to &quot;服务地址&quot;">​</a></h2><p>Ham MCP 服务采用 <strong>Streamable HTTP</strong> 传输方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mcp.ham.nowcent.cn/mcp</span></span></code></pre></div><h2 id="认证方式" tabindex="-1">认证方式 <a class="header-anchor" href="#认证方式" aria-label="Permalink to &quot;认证方式&quot;">​</a></h2><p>Ham MCP 服务支持两种认证方式：</p><ul><li><strong>OAuth 动态注册（推荐）</strong>：客户端在首次连接时自动完成注册与授权，无需手动创建 API Key，适用于支持 MCP OAuth 的现代客户端（如 Claude Desktop、Cursor、ChatGPT、Codex 等）。</li><li><strong>API Key</strong>：在 Ham 控制台手动生成 API Key，通过 <code>Authorization: Bearer &lt;API_KEY&gt;</code> 请求头进行鉴权，适用于不支持 OAuth 动态注册或需要长期凭证的场景。</li></ul><h3 id="oauth-动态注册-推荐" tabindex="-1">OAuth 动态注册（推荐） <a class="header-anchor" href="#oauth-动态注册-推荐" aria-label="Permalink to &quot;OAuth 动态注册（推荐）&quot;">​</a></h3><p>Ham MCP 服务遵循 <a href="https://modelcontextprotocol.io/specification/draft/basic/authorization" target="_blank" rel="noreferrer">MCP Authorization 规范</a>，实现了 <a href="https://datatracker.ietf.org/doc/html/rfc7591" target="_blank" rel="noreferrer">OAuth 2.0 动态客户端注册（RFC 7591）</a> 与 <a href="https://datatracker.ietf.org/doc/html/rfc9728" target="_blank" rel="noreferrer">受保护资源元数据（RFC 9728）</a>。</p><p>接入流程由客户端自动完成：</p><ol><li>客户端访问服务地址，收到 <code>401 Unauthorized</code> 响应；</li><li>客户端通过 <code>/.well-known/oauth-protected-resource</code> 发现授权服务器；</li><li>客户端通过动态注册接口自动注册，获取 <code>client_id</code>；</li><li>浏览器跳转至 Ham 授权页面，登录并同意授权后返回客户端；</li><li>客户端获得访问凭证，后续请求自动携带，无需手动配置。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>使用动态注册时，你只需在客户端中填入服务地址 <code>https://mcp.ham.nowcent.cn/mcp</code>，其余流程均由客户端自动处理。</p></div><h3 id="api-key" tabindex="-1">API Key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API Key&quot;">​</a></h3><p>如果你的客户端不支持 OAuth 动态注册，或希望使用长期固定凭证，可以在 Ham 控制台生成 API Key 后手动配置。</p><h4 id="获取-api-key" tabindex="-1">获取 API Key <a class="header-anchor" href="#获取-api-key" aria-label="Permalink to &quot;获取 API Key&quot;">​</a></h4><ol><li>访问 <a href="https://ham.nowcent.cn/console/tokens" target="_blank" rel="noreferrer">Ham 控制台 - API Keys 管理</a></li><li>点击「创建 API Key」</li><li>为 API Key 添加描述（如「Claude Desktop」），方便后续管理</li><li>复制生成的 API Key（<strong>仅显示一次，请妥善保管</strong>）</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>请勿将 API Key 分享给他人。API Key 等同于你的账号凭证，泄露可能导致个人信息被访问。</p></div>',21)])])}const u=a(l,[["render",i]]);export{m as __pageData,u as default};
